impl Errno {
    /// Encodes the error as a raw syscall return value (`-errno`).
    pub const fn to_ret(self) -> Slong {
        self.0.wrapping_neg()
    }
    /// Decodes a raw syscall return value: `Some` for Linux's error range `-4095..=-1`.
    pub fn from_ret(ret: Slong) -> Option<Self> {
        if (-4095..=-1).contains(&ret) {
            Some(Self(-ret))
        } else {
            None
        }
    }
}

impl fmt::Debug for Errno {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.name() {
            Some(name) => f.write_str(name),
            None => write!(f, "Errno({})", self.0),
        }
    }
}

impl GuestLayout for Errno {
    const SIZE: usize = <i32 as GuestLayout>::SIZE;
    const ALIGN: usize = <i32 as GuestLayout>::ALIGN;
    const ZERO: Self = Self(0);
    fn read_from(bytes: &[u8]) -> Option<Self> {
        <i32 as GuestLayout>::read_from(bytes).map(Self)
    }
    fn write_to(&self, out: &mut [u8]) {
        self.0.write_to(out);
    }
}

/// `statx` timestamp (`struct statx_timestamp`).
///
/// C: `struct statx_timestamp`
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct StatxTimestamp {
    pub tv_sec: i64,
    pub tv_nsec: u32,
    /// musl: `__pad`.
    pub reserved: i32,
}
const _: () = {
    assert!(core::mem::size_of::<StatxTimestamp>() == 16);
    assert!(core::mem::align_of::<StatxTimestamp>() == 8);
    assert!(core::mem::offset_of!(StatxTimestamp, tv_sec) == 0);
    assert!(core::mem::offset_of!(StatxTimestamp, tv_nsec) == 8);
    assert!(core::mem::offset_of!(StatxTimestamp, reserved) == 12);
};
impl Default for StatxTimestamp {
    fn default() -> Self {
        <Self as GuestLayout>::ZERO
    }
}
impl GuestLayout for StatxTimestamp {
    const SIZE: usize = 16;
    const ALIGN: usize = 8;
    const ZERO: Self = Self {
        tv_sec: <i64 as GuestLayout>::ZERO,
        tv_nsec: <u32 as GuestLayout>::ZERO,
        reserved: <i32 as GuestLayout>::ZERO,
    };
    fn read_from(bytes: &[u8]) -> Option<Self> {
        let bytes = bytes.get(..Self::SIZE)?;
        Some(Self {
            tv_sec: GuestLayout::read_from(&bytes[0..])?,
            tv_nsec: GuestLayout::read_from(&bytes[8..])?,
            reserved: GuestLayout::read_from(&bytes[12..])?,
        })
    }
    fn write_to(&self, out: &mut [u8]) {
        let out = &mut out[..Self::SIZE];
        out.fill(0);
        self.tv_sec.write_to(&mut out[0..]);
        self.tv_nsec.write_to(&mut out[8..]);
        self.reserved.write_to(&mut out[12..]);
    }
}
