/// Legacy lock with 32-bit offsets (`struct flock`), only reachable with kernel `F_GETLK` (5)..
/// `F_SETLKW` (7). musl's `struct flock` is the 64-bit `flock64`.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Flock {
    pub l_type: LockType,
    pub l_whence: i16,
    pub l_start: Slong,
    pub l_len: Slong,
    pub l_pid: Pid,
}
const _: () = {
    assert!(core::mem::size_of::<Flock>() == 16);
    assert!(core::mem::align_of::<Flock>() == 4);
    assert!(core::mem::offset_of!(Flock, l_type) == 0);
    assert!(core::mem::offset_of!(Flock, l_whence) == 2);
    assert!(core::mem::offset_of!(Flock, l_start) == 4);
    assert!(core::mem::offset_of!(Flock, l_len) == 8);
    assert!(core::mem::offset_of!(Flock, l_pid) == 12);
};
impl Default for Flock {
    fn default() -> Self {
        <Self as GuestLayout>::ZERO
    }
}
impl GuestLayout for Flock {
    const SIZE: usize = 16;
    const ALIGN: usize = 4;
    const ZERO: Self = Self {
        l_type: <LockType as GuestLayout>::ZERO,
        l_whence: <i16 as GuestLayout>::ZERO,
        l_start: <Slong as GuestLayout>::ZERO,
        l_len: <Slong as GuestLayout>::ZERO,
        l_pid: <Pid as GuestLayout>::ZERO,
    };
    fn read_from(bytes: &[u8]) -> Option<Self> {
        let bytes = bytes.get(..Self::SIZE)?;
        Some(Self {
            l_type: GuestLayout::read_from(&bytes[0..])?,
            l_whence: GuestLayout::read_from(&bytes[2..])?,
            l_start: GuestLayout::read_from(&bytes[4..])?,
            l_len: GuestLayout::read_from(&bytes[8..])?,
            l_pid: GuestLayout::read_from(&bytes[12..])?,
        })
    }
    fn write_to(&self, out: &mut [u8]) {
        let out = &mut out[..Self::SIZE];
        out.fill(0);
        self.l_type.write_to(&mut out[0..]);
        self.l_whence.write_to(&mut out[2..]);
        self.l_start.write_to(&mut out[4..]);
        self.l_len.write_to(&mut out[8..]);
        self.l_pid.write_to(&mut out[12..]);
    }
}
