/// `futex_waitv`/`futex_requeue` waiter (`struct futex_waitv`).
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct FutexWaitv {
    pub val: u64,
    /// Guest address of the futex word, zero-extended.
    pub uaddr: u64,
    pub flags: Futex2Flags,
    pub reserved: u32,
}
const _: () = {
    assert!(core::mem::size_of::<FutexWaitv>() == 24);
    assert!(core::mem::align_of::<FutexWaitv>() == 8);
    assert!(core::mem::offset_of!(FutexWaitv, val) == 0);
    assert!(core::mem::offset_of!(FutexWaitv, uaddr) == 8);
    assert!(core::mem::offset_of!(FutexWaitv, flags) == 16);
    assert!(core::mem::offset_of!(FutexWaitv, reserved) == 20);
};
impl Default for FutexWaitv {
    fn default() -> Self {
        <Self as GuestLayout>::ZERO
    }
}
impl GuestLayout for FutexWaitv {
    const SIZE: usize = 24;
    const ALIGN: usize = 8;
    const ZERO: Self = Self {
        val: <u64 as GuestLayout>::ZERO,
        uaddr: <u64 as GuestLayout>::ZERO,
        flags: <Futex2Flags as GuestLayout>::ZERO,
        reserved: <u32 as GuestLayout>::ZERO,
    };
    fn read_from(bytes: &[u8]) -> Option<Self> {
        let bytes = bytes.get(..Self::SIZE)?;
        Some(Self {
            val: GuestLayout::read_from(&bytes[0..])?,
            uaddr: GuestLayout::read_from(&bytes[8..])?,
            flags: GuestLayout::read_from(&bytes[16..])?,
            reserved: GuestLayout::read_from(&bytes[20..])?,
        })
    }
    fn write_to(&self, out: &mut [u8]) {
        let out = &mut out[..Self::SIZE];
        out.fill(0);
        self.val.write_to(&mut out[0..]);
        self.uaddr.write_to(&mut out[8..]);
        self.flags.write_to(&mut out[16..]);
        self.reserved.write_to(&mut out[20..]);
    }
}
