/// `clock_adjtime64` return values (`TIME_*`; `linux/timex.h`).
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub struct ClockState(pub i32);
impl ClockState {
    pub const TIME_OK: Self = Self(0);
    pub const TIME_INS: Self = Self(1);
    pub const TIME_DEL: Self = Self(2);
    pub const TIME_OOP: Self = Self(3);
    pub const TIME_WAIT: Self = Self(4);
    pub const TIME_BAD: Self = Self(5);
    pub const TIME_ERROR: Self = Self(5);
    /// All named values, in definition order (aliases included).
    pub const MEMBERS: &'static [(&'static str, Self)] = &[
        ("TIME_OK", Self::TIME_OK),
        ("TIME_INS", Self::TIME_INS),
        ("TIME_DEL", Self::TIME_DEL),
        ("TIME_OOP", Self::TIME_OOP),
        ("TIME_WAIT", Self::TIME_WAIT),
        ("TIME_BAD", Self::TIME_BAD),
        ("TIME_ERROR", Self::TIME_ERROR),
    ];
    /// Name of the first constant with this value, if any.
    pub const fn name(self) -> Option<&'static str> {
        match self.0 {
            0 => Some("TIME_OK"),
            1 => Some("TIME_INS"),
            2 => Some("TIME_DEL"),
            3 => Some("TIME_OOP"),
            4 => Some("TIME_WAIT"),
            5 => Some("TIME_BAD"),
            _ => None,
        }
    }
}

impl fmt::Debug for ClockState {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.name() {
            Some(name) => f.write_str(name),
            None => write!(f, "ClockState({})", self.0),
        }
    }
}

impl GuestLayout for ClockState {
    const SIZE: usize = <i32 as GuestLayout>::SIZE;
    const ALIGN: usize = <i32 as GuestLayout>::ALIGN;
    const ZERO: Self = Self(0);
    fn read_from(bytes: &[u8]) -> Option<Self> {
        <i32 as GuestLayout>::read_from(bytes).map(Self)
    }
    fn write_to(&self, out: &mut [u8]) {
        self.0.write_to(out);
    }
}

