/// `SOCK_NONBLOCK`/`SOCK_CLOEXEC` for `socket`, `socketpair` (ORed into the type) and `accept4`.
///
/// C: `int`
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
pub struct SocketFlags(pub u32);
impl SocketFlags {
    pub const SOCK_NONBLOCK: Self = Self(0x800);
    pub const SOCK_CLOEXEC: Self = Self(0x80000);
    /// All named values, in definition order (aliases included).
    pub const MEMBERS: &'static [(&'static str, Self)] = &[
        ("SOCK_NONBLOCK", Self::SOCK_NONBLOCK),
        ("SOCK_CLOEXEC", Self::SOCK_CLOEXEC),
    ];

    pub const fn empty() -> Self {
        Self(0)
    }
    pub const fn bits(self) -> u32 {
        self.0
    }
    pub const fn is_empty(self) -> bool {
        self.0 == 0
    }
    /// Whether all bits of `other` are set.
    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
    /// Whether any bit of `other` is set.
    pub const fn intersects(self, other: Self) -> bool {
        self.0 & other.0 != 0
    }
}

impl fmt::Debug for SocketFlags {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("SocketFlags(")?;
        let mut rest = self.0;
        let mut first = true;
        for (name, flag) in Self::MEMBERS {
            if flag.0 != 0 && self.contains(*flag) && rest & flag.0 != 0 {
                if !first {
                    f.write_str(" | ")?;
                }
                f.write_str(name)?;
                first = false;
                rest &= !flag.0;
            }
        }
        if rest != 0 || first {
            if !first {
                f.write_str(" | ")?;
            }
            write!(f, "{rest:#x}")?;
        }
        f.write_str(")")
    }
}
