/// IPC permissions (asm-generic `struct ipc64_perm`). The zero-length `__pad1` is omitted.
///
/// C: `struct ipc_perm`
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Ipc64Perm {
    pub key: Key,
    pub uid: Uid,
    pub gid: Gid,
    pub cuid: Uid,
    pub cgid: Gid,
    pub mode: Mode,
    /// musl: `int __ipc_perm_seq`, covering `seq` and `__pad2` (little-endian).
    pub seq: u16,
    /// No C assert: part of musl's 32-bit `__ipc_perm_seq`.
    pub pad2: u16,
    /// musl: `__pad1`.
    pub unused1: Ulong,
    /// musl: `__pad2`.
    pub unused2: Ulong,
}
const _: () = {
    assert!(core::mem::size_of::<Ipc64Perm>() == 36);
    assert!(core::mem::align_of::<Ipc64Perm>() == 4);
    assert!(core::mem::offset_of!(Ipc64Perm, key) == 0);
    assert!(core::mem::offset_of!(Ipc64Perm, uid) == 4);
    assert!(core::mem::offset_of!(Ipc64Perm, gid) == 8);
    assert!(core::mem::offset_of!(Ipc64Perm, cuid) == 12);
    assert!(core::mem::offset_of!(Ipc64Perm, cgid) == 16);
    assert!(core::mem::offset_of!(Ipc64Perm, mode) == 20);
    assert!(core::mem::offset_of!(Ipc64Perm, seq) == 24);
    assert!(core::mem::offset_of!(Ipc64Perm, pad2) == 26);
    assert!(core::mem::offset_of!(Ipc64Perm, unused1) == 28);
    assert!(core::mem::offset_of!(Ipc64Perm, unused2) == 32);
};
impl Default for Ipc64Perm {
    fn default() -> Self {
        <Self as GuestLayout>::ZERO
    }
}
impl GuestLayout for Ipc64Perm {
    const SIZE: usize = 36;
    const ALIGN: usize = 4;
    const ZERO: Self = Self {
        key: <Key as GuestLayout>::ZERO,
        uid: <Uid as GuestLayout>::ZERO,
        gid: <Gid as GuestLayout>::ZERO,
        cuid: <Uid as GuestLayout>::ZERO,
        cgid: <Gid as GuestLayout>::ZERO,
        mode: <Mode as GuestLayout>::ZERO,
        seq: <u16 as GuestLayout>::ZERO,
        pad2: <u16 as GuestLayout>::ZERO,
        unused1: <Ulong as GuestLayout>::ZERO,
        unused2: <Ulong as GuestLayout>::ZERO,
    };
    fn read_from(bytes: &[u8]) -> Option<Self> {
        let bytes = bytes.get(..Self::SIZE)?;
        Some(Self {
            key: GuestLayout::read_from(&bytes[0..])?,
            uid: GuestLayout::read_from(&bytes[4..])?,
            gid: GuestLayout::read_from(&bytes[8..])?,
            cuid: GuestLayout::read_from(&bytes[12..])?,
            cgid: GuestLayout::read_from(&bytes[16..])?,
            mode: GuestLayout::read_from(&bytes[20..])?,
            seq: GuestLayout::read_from(&bytes[24..])?,
            pad2: GuestLayout::read_from(&bytes[26..])?,
            unused1: GuestLayout::read_from(&bytes[28..])?,
            unused2: GuestLayout::read_from(&bytes[32..])?,
        })
    }
    fn write_to(&self, out: &mut [u8]) {
        let out = &mut out[..Self::SIZE];
        out.fill(0);
        self.key.write_to(&mut out[0..]);
        self.uid.write_to(&mut out[4..]);
        self.gid.write_to(&mut out[8..]);
        self.cuid.write_to(&mut out[12..]);
        self.cgid.write_to(&mut out[16..]);
        self.mode.write_to(&mut out[20..]);
        self.seq.write_to(&mut out[24..]);
        self.pad2.write_to(&mut out[26..]);
        self.unused1.write_to(&mut out[28..]);
        self.unused2.write_to(&mut out[32..]);
    }
}
/// `msgctl` buffer (asm-generic `struct msqid64_ds`, times split into low/high words).
