impl fmt::Debug for TermiosLflag {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("TermiosLflag(")?;
        let mut rest = self.0;
        let mut first = true;
        for (name, flag) in Self::MEMBERS {
            if flag.0 != 0 && self.contains(*flag) && rest & flag.0 != 0 {
                if !first {
                    f.write_str(" | ")?;
                }
                f.write_str(name)?;
                first = false;
                rest &= !flag.0;
            }
        }
        if rest != 0 || first {
            if !first {
                f.write_str(" | ")?;
            }
            write!(f, "{rest:#x}")?;
        }
        f.write_str(")")
    }
}
